1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eceef1;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2227;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 44px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow-x: auto;
33	    white-space: nowrap;
34	  }
35	  .keys {
36	    display: grid;
37	    grid-template-columns: repeat(4, 1fr);
38	    gap: 10px;
39	  }
40	  button {
41	    font: inherit;
42	    font-size: 22px;
43	    height: 60px;
44	    border: none;
45	    border-radius: 12px;
46	    background: #3a3e45;
47	    color: #fff;
48	    cursor: pointer;
49	  }
50	  button:active { filter: brightness(1.25); }
51	  button.op { background: #f59e0b; }
52	  button.clear { background: #9ca3af; color: #111; }
53	  button.wide { grid-column: span 2; }
54	</style>
55	</head>
56	<body>
57	<div class="calc">
58	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
59	  <div class="keys">
60	    <button class="clear wide" data-testid="key-lparen">(</button>
61	    <button class="clear wide" data-testid="key-rparen">)</button>
62	    <!-- [REQ-006] no % key; AC takes its space -->
63	    <button class="clear wide" data-testid="key-clear">AC</button>
64	    <button class="clear" data-testid="key-sign">±</button>
65	    <button class="op" data-testid="key-div" data-op="/">÷</button>
66	    <button data-testid="key-7" data-digit="7">7</button>
67	    <button data-testid="key-8" data-digit="8">8</button>
68	    <button data-testid="key-9" data-digit="9">9</button>
69	    <button class="op" data-testid="key-mul" data-op="*">×</button>
70	    <button data-testid="key-4" data-digit="4">4</button>
71	    <button data-testid="key-5" data-digit="5">5</button>
72	    <button data-testid="key-6" data-digit="6">6</button>
73	    <button class="op" data-testid="key-sub" data-op="-">−</button>
74	    <button data-testid="key-1" data-digit="1">1</button>
75	    <button data-testid="key-2" data-digit="2">2</button>
76	    <button data-testid="key-3" data-digit="3">3</button>
77	    <button class="op" data-testid="key-add" data-op="+">+</button>
78	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
79	    <button data-testid="key-dot">.</button>
80	    <button class="op" data-testid="key-equals">=</button>
81	  </div>
82	</div>
83	<script>
84	  var displayEl = document.querySelector('[data-testid="calc-display"]');
85	
86	  var state;
87	
88	  // [REQ-001] reset to the initial state: display 0, nothing pending
89	  // [REQ-003] clear also leaves the error state
90	  function clearAll() {
91	    state = { entry: '0', stored: null, op: null, fresh: true, typing: false, error: false, groups: [] };
92	    render();
93	  }
94	
95	  // [REQ-001] apply an operator
96	  // [REQ-003] exact result, never rounded; division by zero returns null (error)
97	  function compute(a, op, b) {
98	    if (op === '+') return a + b;
99	    if (op === '-') return a - b;
100	    if (op === '*') return a * b;
101	    if (b === 0) return null;
102	    return a / b;
103	  }
104	
105	  // [REQ-003] presentation only: at most 10 significant digits, no trailing zeros,
106	  // exponential only when |n| >= 1e10 or |n| < 1e-9
107	  function formatNumber(n) {
108	    if (n === 0) return '0';
109	    if (!isFinite(n)) return String(n);
110	    var parts = n.toExponential(9).split('e');
111	    var exp = Number(parts[1]);
112	    if (exp >= 10 || exp < -9) {
113	      return parts[0].replace(/\.?0+$/, '') + 'e' + (exp >= 0 ? '+' : '') + exp;
114	    }
115	    var sign = n < 0 ? '-' : '';
116	    var digits = parts[0].replace('-', '').replace('.', '');
117	    var intPart, fracPart;
118	    if (exp >= 0) {
119	      intPart = digits.slice(0, exp + 1);
120	      fracPart = digits.slice(exp + 1);
121	    } else {
122	      intPart = '0';
123	      fracPart = new Array(-exp).join('0') + digits;
124	    }
125	    fracPart = fracPart.replace(/0+$/, '');
126	    return sign + intPart + (fracPart ? '.' + fracPart : '');
127	  }
128	
129	  // [REQ-003] enter the error state
130	  function setError() {
131	    state.error = true;
132	    render();
133	  }
134	
135	  // [REQ-001] digits build the entry
136	  // [REQ-004] a shown result (not typed) is replaced, not appended to
137	  function inputDigit(d) {
138	    if (state.fresh || !state.typing) {
139	      state.entry = d;
140	      state.fresh = false;
141	    } else {
142	      state.entry = state.entry === '0' ? d : state.entry + d;
143	    }
144	    state.typing = true;
145	    render();
146	  }
147	
148	  // [REQ-001] at most one decimal point per entry
149	  function inputDot() {
150	    if (state.fresh || !state.typing) {
151	      state.entry = '0.';
152	      state.fresh = false;
153	    } else if (state.entry.indexOf('.') === -1) {
154	      state.entry += '.';
155	    }
156	    state.typing = true;
157	    render();
158	  }
159	
160	  // [REQ-004] flip the sign of the current entry; a typed entry keeps its text
161	  function inputSign() {
162	    if (state.typing) {
163	      if (state.entry !== '0') {
164	        state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
165	      }
166	    } else {
167	      state.entry = String(-Number(state.entry) || 0);
168	      state.fresh = false;
169	    }
170	    render();
171	  }
172	
173	  // [REQ-001] store the operator; chains evaluate left to right
174	  // [REQ-002] immediate execution: an operator first applies the waiting op and shows the
175	  // running result; no precedence, so 2 + 3 × 4 = is 20
176	  function inputOp(op) {
177	    var current = Number(state.entry);
178	    if (state.op !== null && !state.fresh) {
179	      var result = compute(state.stored, state.op, current);
180	      if (result === null) return setError();
181	      state.entry = String(result);
182	      state.stored = result;
183	    } else if (state.op === null) {
184	      state.stored = current;
185	    }
186	    state.op = op;
187	    state.fresh = true;
188	    state.typing = false;
189	    render();
190	  }
191	
192	  // [REQ-005] open a group: park the waiting stored value and op; the group starts empty
193	  function openGroup() {
194	    state.groups.push({ stored: state.op === null ? null : state.stored, op: state.op });
195	    state.stored = null;
196	    state.op = null;
197	    state.fresh = true;
198	    state.typing = false;
199	    render();
200	  }
201	
202	  // [REQ-005] close the innermost group: its result becomes the entry for the outer op
203	  function closeGroup() {
204	    if (state.groups.length === 0) return;
205	    var value = Number(state.entry);
206	    if (state.op !== null) {
207	      value = compute(state.stored, state.op, value);
208	      if (value === null) return setError();
209	    }
210	    var outer = state.groups.pop();
211	    state.stored = outer.stored;
212	    state.op = outer.op;
213	    state.entry = String(value);
214	    state.fresh = false;
215	    state.typing = false;
216	    render();
217	  }
218	
219	  // [REQ-001] equals shows the result of stored op entry
220	  // [REQ-005] equals first closes any open groups
221	  function equals() {
222	    while (state.groups.length > 0) {
223	      closeGroup();
224	      if (state.error) return;
225	    }
226	    if (state.op === null) return;
227	    var result = compute(state.stored, state.op, Number(state.entry));
228	    if (result === null) return setError();
229	    state.entry = String(result);
230	    state.stored = null;
231	    state.op = null;
232	    state.fresh = true;
233	    state.typing = false;
234	    render();
235	  }
236	
237	  // [REQ-001] data-value holds String(value)
238	  // [REQ-003] typed entry shown as typed; other numbers formatted at render time only;
239	  // data-value stays exact; data-error always present
240	  function render() {
241	    var value = Number(state.entry);
242	    if (state.error) {
243	      displayEl.textContent = 'Error';
244	      displayEl.setAttribute('data-value', 'NaN');
245	    } else {
246	      displayEl.textContent = state.typing ? state.entry : formatNumber(value);
247	      displayEl.setAttribute('data-value', String(value));
248	    }
249	    displayEl.setAttribute('data-error', state.error ? 'true' : 'false');
250	  }
251	
252	  document.querySelector('.keys').addEventListener('click', function (e) {
253	    var btn = e.target.closest('button');
254	    if (!btn) return;
255	    var id = btn.getAttribute('data-testid');
256	    // [REQ-003] in the error state only clear works
257	    if (state.error && id !== 'key-clear') return;
258	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
259	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
260	    else if (id === 'key-dot') inputDot();
261	    else if (id === 'key-equals') equals();
262	    else if (id === 'key-sign') inputSign();
263	    else if (id === 'key-lparen') openGroup();
264	    else if (id === 'key-rparen') closeGroup();
265	    else if (id === 'key-clear') clearAll();
266	  });
267	
268	  clearAll();
269	</script>
270	</body>
271	</html>
